mkitem!{mkenum!{#[doc = " When type-checking an expression, we propagate downward"] #[doc = " whatever type hint we are able in the form of an `Expectation`."] #[derive (Copy , Clone , Debug)] pub (crate) enum Expectation < 'tcx > { #[doc = " We know nothing about what type this expression should have."] NoExpectation , #[doc = " This expression should have the type given (or some subtype)."] ExpectHasType (Ty < 'tcx >) , #[doc = " This expression will be cast to the `Ty`."] ExpectCastableToType (Ty < 'tcx >) , #[doc = " This rvalue expression will be wrapped in `&` or `Box` and coerced"] #[doc = " to `&Ty` or `Box<Ty>`, respectively. `Ty` is `[A]` or `Trait`."] ExpectRvalueLikeUnsized (Ty < 'tcx >) , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > Expectation < 'tcx > { pub (super) fn try_structurally_resolve_and_adjust_for_branches (& self , fcx : & FnCtxt < 'a , 'tcx > , span : Span ,) -> Expectation < 'tcx > { match * self { ExpectHasType (ety) => { let ety = fcx . try_structurally_resolve_type (span , ety) ; if ! ety . is_ty_var () { ExpectHasType (ety) } else { NoExpectation } } ExpectRvalueLikeUnsized (ety) => ExpectRvalueLikeUnsized (ety) , _ => NoExpectation , } } #[doc = " Provides an expectation for an rvalue expression given an *optional*"] #[doc = " hint, which is not required for type safety (the resulting type might"] #[doc = " be checked higher up, as is the case with `&expr` and `box expr`), but"] #[doc = " is useful in determining the concrete type."] #[doc = ""] #[doc = " The primary use case is where the expected type is a wide pointer,"] #[doc = " like `&[isize]`. For example, consider the following statement:"] #[doc = ""] #[doc = "    let x: &[isize] = &[1, 2, 3];"] #[doc = ""] #[doc = " In this case, the expected type for the `&[1, 2, 3]` expression is"] #[doc = " `&[isize]`. If however we were to say that `[1, 2, 3]` has the"] #[doc = " expectation `ExpectHasType([isize])`, that would be too strong --"] #[doc = " `[1, 2, 3]` does not have the type `[isize]` but rather `[isize; 3]`."] #[doc = " It is only the `&[1, 2, 3]` expression as a whole that can be coerced"] #[doc = " to the type `&[isize]`. Therefore, we propagate this more limited hint,"] #[doc = " which still is useful, because it informs integer literals and the like."] #[doc = " See the test case `test/ui/coerce-expect-unsized.rs` and #20169"] #[doc = " for examples of where this comes up,."] pub (super) fn rvalue_hint (fcx : & FnCtxt < 'a , 'tcx > , ty : Ty < 'tcx >) -> Expectation < 'tcx > { match fcx . tcx . struct_tail_raw (ty , | ty | ty , | | { }) . kind () { ty :: Slice (_) | ty :: Str | ty :: Dynamic (..) => ExpectRvalueLikeUnsized (ty) , _ => ExpectHasType (ty) , } } #[doc = " Resolves `expected` by a single level if it is a variable. If"] #[doc = " there is no expected type or resolution is not possible (e.g.,"] #[doc = " no constraints yet present), just returns `self`."] fn resolve (self , fcx : & FnCtxt < 'a , 'tcx >) -> Expectation < 'tcx > { match self { NoExpectation => NoExpectation , ExpectCastableToType (t) => ExpectCastableToType (fcx . resolve_vars_if_possible (t)) , ExpectHasType (t) => ExpectHasType (fcx . resolve_vars_if_possible (t)) , ExpectRvalueLikeUnsized (t) => ExpectRvalueLikeUnsized (fcx . resolve_vars_if_possible (t)) , } } pub (super) fn to_option (self , fcx : & FnCtxt < 'a , 'tcx >) -> Option < Ty < 'tcx > > { match self . resolve (fcx) { NoExpectation => None , ExpectCastableToType (ty) | ExpectHasType (ty) | ExpectRvalueLikeUnsized (ty) => Some (ty) , } } #[doc = " It sometimes happens that we want to turn an expectation into"] #[doc = " a **hard constraint** (i.e., something that must be satisfied"] #[doc = " for the program to type-check). `only_has_type` will return"] #[doc = " such a constraint, if it exists."] pub (super) fn only_has_type (self , fcx : & FnCtxt < 'a , 'tcx >) -> Option < Ty < 'tcx > > { match self { ExpectHasType (ty) => Some (fcx . resolve_vars_if_possible (ty)) , NoExpectation | ExpectCastableToType (_) | ExpectRvalueLikeUnsized (_) => None , } } #[doc = " Like `only_has_type`, but instead of returning `None` if no"] #[doc = " hard constraint exists, creates a fresh type variable."] pub (super) fn coercion_target_type (self , fcx : & FnCtxt < 'a , 'tcx > , span : Span) -> Ty < 'tcx > { self . only_has_type (fcx) . unwrap_or_else (| | fcx . next_ty_var (span)) } }}}